<?php $monday=(new DateTimeImmutable($boardWeek))->modify('monday this week');$days=[];for($i=0;$i<7;$i++)$days[$monday->modify('+'.$i.' days')->format('Y-m-d')]=$monday->modify('+'.$i.' days')->format('D M j');$rows=['open'=>['name'=>'Open shifts','shifts'=>[]]];foreach($data['people'] as $person)$rows[(string)$person['membership_id']]=['name'=>$person['name'],'shifts'=>[]];foreach($boardShifts as $shift){$key=$shift['assigned_membership_id']?(string)$shift['assigned_membership_id']:'open';if(!isset($rows[$key]))$rows[$key]=['name'=>$shift['assigned_name']?:'Unlisted employee','shifts'=>[]];$rows[$key]['shifts'][]=$shift;}$admin=$scheduleManager;?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Weekly Schedule · Atlas</title><link rel="stylesheet" href="<?=esc(url_for('assets/app.css'))?>"></head><body class="standalone-with-nav"><?=standaloneSidebar($navGroups,$route,$admin,$org,$user,$location)?><main class="page-wrap standalone-workspace"><header class="page-header"><div><p class="eyebrow">WEEKLY SCHEDULE BOARD</p><h1>Week of <?=esc($monday->format('F j, Y'))?></h1><p>Move, reassign, and review shifts with live eligibility safeguards.</p></div><div><a class="button secondary" href="<?=esc(url_for('command-center'))?>">Command center</a><a class="button primary" href="<?=esc(url_for('master-schedule'))?>">Master Schedule</a></div></header><?php if($notice):?><div class="page-flash success"><span>✓</span><?=esc($notice['message'])?></div><?php endif;?><?php if($error):?><div class="form-alert error"><?=esc($error)?></div><?php endif;?>
<form method="get" class="schedule-filters"><input type="hidden" name="route" value="schedule"><label>Week<input type="date" name="week" value="<?=esc($monday->format('Y-m-d'))?>"></label><label>Location<select name="location_id"><option value="">All locations</option><?php foreach($data['locations'] as $item):?><option value="<?=$item['id']?>" <?=$boardLocation===$item['id']?'selected':''?>><?=esc($item['name'])?></option><?php endforeach;?></select></label><label>Department<select name="department_id"><option value="">All departments</option><?php foreach($data['departments'] as $item):?><option value="<?=$item['id']?>" <?=$boardDepartment===$item['id']?'selected':''?>><?=esc($item['name'])?></option><?php endforeach;?></select></label><button class="button secondary">Apply view</button></form><?php if($admin):?><details class="panel"><summary class="button primary">Create open shift</summary><form method="post" class="stack-form two-column" style="padding:18px"><?=Csrf::field()?><input type="hidden" name="action" value="create_shift"><input type="hidden" name="eligibility_mode" value="exact"><label>Date<input type="date" name="shift_date" required></label><label>Location<select name="location_id"><?php foreach($data['locations'] as $item):?><option value="<?=$item['id']?>"><?=esc($item['name'])?></option><?php endforeach;?></select></label><label>Department<select name="department_id"><?php foreach($data['departments'] as $item):?><option value="<?=$item['id']?>"><?=esc($item['name'])?></option><?php endforeach;?></select></label><label>Position<select name="exact_position_id"><?php foreach($data['positions'] as $item):?><option value="<?=$item['id']?>"><?=esc($item['name'])?></option><?php endforeach;?></select></label><label>Start<input type="time" name="starts_at" required></label><label>End<input type="time" name="ends_at" required></label><button class="button primary">Create shift</button></form></details><?php endif;?>
<section class="weekly-board"><div class="board-head"><strong>Employee</strong><?php foreach($days as $label):?><strong><?=$label?></strong><?php endforeach;?></div><?php foreach($rows as $memberKey=>$row):?><div class="board-row"><div class="board-person"><strong><?=esc($row['name'])?></strong><small><?=count($row['shifts'])?> shifts</small><?php if($memberKey!=='open'):?><a href="<?=esc(url_for('employee?membership_id='.$memberKey))?>">Profile</a><?php endif;?></div><?php foreach($days as $date=>$label):?><div class="board-day" data-drop-date="<?=$date?>" data-drop-member="<?=$memberKey==='open'?'':$memberKey?>"><?php foreach($row['shifts'] as $shift):if($shift['shift_date']!==$date)continue;?><article class="board-shift <?=$shift['status']==='open'?'open':''?>" draggable="<?=$admin?'true':'false'?>" data-shift-id="<?=$shift['id']?>"><strong><?=esc(date('g:i A',strtotime($shift['starts_at'])))?></strong><span><?=esc($shift['department_name'])?></span><small><?=esc($shift['position_name']?:'Flexible')?></small><?php if($admin):?><details><summary>Manage</summary><form method="post" class="stack-form"><?=Csrf::field()?><input type="hidden" name="action" value="move_shift"><input type="hidden" name="shift_id" value="<?=$shift['id']?>"><input type="hidden" name="week" value="<?=$monday->format('Y-m-d')?>"><label>Date<input type="date" name="shift_date" value="<?=$shift['shift_date']?>"></label><label>Start<input type="time" name="starts_at" value="<?=substr($shift['starts_at'],0,5)?>"></label><label>End<input type="time" name="ends_at" value="<?=substr($shift['ends_at'],0,5)?>"></label><label>Employee<select name="membership_id"><option value="">Open</option><?php foreach($data['people'] as $person):?><option value="<?=$person['membership_id']?>" <?=$person['membership_id']==$shift['assigned_membership_id']?'selected':''?>><?=esc($person['name'])?></option><?php endforeach;?></select></label><label>Reason<input name="reason"></label><label class="check-label"><input type="checkbox" name="require_eligible" value="1" checked><span>Require full eligibility</span></label><button class="button primary">Save move</button></form><a href="<?=esc(url_for('schedule?week='.$monday->format('Y-m-d').'&recommend_shift='.$shift['id']))?>">Find replacement</a></details><?php endif;?></article><?php endforeach;?></div><?php endforeach;?></div><?php endforeach;?></section>
<?php if($selectedRecommendationShift):?><section class="panel"><h2>Recommended replacements</h2><?php foreach($replacementCandidates as $candidate):?><div class="planning-row"><span><strong><?=esc($candidate['name'])?></strong><small><?=$candidate['scheduled_hours']?> scheduled hours · <?=esc(ucfirst($candidate['eligibility_result']))?></small></span><b class="state-pill covered">Score <?=$candidate['recommendation_score']?></b></div><?php endforeach;?></section><?php endif;?><?php if($admin):?><section class="panel"><h2>Recent schedule history</h2><?php foreach(array_slice($shiftHistory,0,20) as $event):?><div class="planning-row"><span><strong><?=esc(ucwords(str_replace('_',' ',$event['action'])))?> · <?=esc($event['shift_date'])?></strong><small><?=esc($event['changed_by_name'].' · '.$event['created_at'].($event['reason']?' · '.$event['reason']:''))?></small></span></div><?php endforeach;?></section><form method="post" id="dragMoveForm" hidden><?=Csrf::field()?><input name="action" value="move_shift"><input name="shift_id"><input name="membership_id"><input name="shift_date"><input name="week" value="<?=$monday->format('Y-m-d')?>"><input name="require_eligible" value="1"><input name="reason" value="Drag-and-drop schedule move"></form><?php endif;?></main><script src="<?=esc(url_for('assets/app.js'))?>"></script></body></html>
